  const liveEvents=storedBookings().filter(item=>item.eventDate).map(item=>{const date=new Date(`${item.eventDate}T00:00:00`);return [String(date.getDate()).padStart(2,'0'),date.toLocaleString('en-IN',{month:'short'}).toUpperCase(),item.eventName||`${item.clientName} ${item.eventType}`,item.eventLocation||item.city||'Location not added',item.eventType]});
