const closeDatePicker=()=>{datePicker.hidden=true;dateButton.setAttribute('aria-expanded','false')};
const formatDateRange=dateValue=>new Date(`${dateValue}T00:00:00`).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
dateButton.addEventListener('click',event=>{event.stopPropagation();datePicker.hidden=!datePicker.hidden;dateButton.setAttribute('aria-expanded',String(!datePicker.hidden))});
document.querySelector('#closeDatePicker').addEventListener('click',closeDatePicker);
document.querySelector('#cancelDateRange').addEventListener('click',closeDatePicker);
document.querySelector('#applyDateRange').addEventListener('click',()=>{if(!dateStart.value||!dateEnd.value||dateStart.value>dateEnd.value){showToast('Choose a valid date range');return}dateButton.childNodes[0].textContent=`${formatDateRange(dateStart.value)} – ${formatDateRange(dateEnd.value)} `;closeDatePicker();showToast('Date range updated')});
document.addEventListener('click',event=>{if(!event.target.closest('.date-picker-wrap'))closeDatePicker()});
document.querySelectorAll('.nav-item').forEach(item=>item.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(nav=>nav.classList.remove('active'));item.classList.add('active');if(item.dataset.view==='Event Calendar'){const today=new Date();calendarState.month=today.getMonth();calendarState.year=today.getFullYear();calendarState.view='month'}renderView(item.dataset.view);document.querySelector('#sidebar').classList.remove('open')}));
const profileButton=document.querySelector('#profileButton');
const profileMenu=document.querySelector('#profileMenu');
const logoutModal=document.querySelector('#logoutModal');
let profileCloseTimer;
function openProfileMenu(){clearTimeout(profileCloseTimer);profileButton.setAttribute('aria-expanded','true');profileMenu.classList.add('open');profileMenu.setAttribute('aria-hidden','false')}
function closeProfileMenu(){profileButton.setAttribute('aria-expanded','false');profileMenu.classList.remove('open');profileMenu.setAttribute('aria-hidden','true')}
function scheduleProfileClose(){clearTimeout(profileCloseTimer);profileCloseTimer=setTimeout(closeProfileMenu,150)}
profileButton.addEventListener('click',event=>{event.stopPropagation();const open=profileMenu.classList.contains('open');if(open)closeProfileMenu();else openProfileMenu()});
profileButton.addEventListener('mouseenter',openProfileMenu);
profileButton.addEventListener('mouseleave',scheduleProfileClose);
profileMenu.addEventListener('mouseenter',openProfileMenu);
profileMenu.addEventListener('mouseleave',scheduleProfileClose);
document.addEventListener('click',event=>{if(event.target.closest('.profile-wrap'))return;closeProfileMenu()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeProfileMenu()});
document.querySelectorAll('[data-profile-action]').forEach(item=>item.addEventListener('click',()=>{const action=item.dataset.profileAction;closeProfileMenu();if(action==='Logout'){logoutModal.classList.remove('hidden');return}if(action==='Dashboard'){renderView('Dashboard');return}renderView(action)}));
document.querySelectorAll('[data-close-modal]').forEach(item=>item.addEventListener('click',()=>logoutModal.classList.add('hidden')));
document.querySelector('#confirmLogout').addEventListener('click',()=>{localStorage.removeItem(authStorageKey);logoutModal.classList.add('hidden');appShell.classList.add('hidden');loginScreen.classList.remove('hidden');document.querySelector('#loginForm').reset();showToast('You have been logged out securely')});
document.querySelector('#notificationButton').addEventListener('click',()=>{renderView('Notifications');showToast(`${notificationsAreRead()?'No unread notifications':'3 unread notifications'}`)});

const canvas=document.querySelector('#luxuryCanvas');
const loginStage=document.querySelector('#loginScreen');
const loginCard=document.querySelector('#loginCard');
const cursorGlow=document.querySelector('#cursorGlow');
const localizedBlur=document.querySelector('#localizedBlur');
const context=canvas?.getContext('2d');
const prefersReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const particles=[];
const pointer={x:-500,y:-500,targetX:-500,targetY:-500};
let canvasWidth=0,canvasHeight=0;

function resizeCanvas(){
  if(!canvas||!context)return;
  const ratio=Math.min(window.devicePixelRatio||1,2);
  canvasWidth=window.innerWidth; canvasHeight=window.innerHeight;
  canvas.width=canvasWidth*ratio; canvas.height=canvasHeight*ratio; canvas.style.width=`${canvasWidth}px`; canvas.style.height=`${canvasHeight}px`; context.setTransform(ratio,0,0,ratio,0,0);
  if(particles.length===0){const amount=window.innerWidth<600?55:125;for(let index=0;index<amount;index++)particles.push({x:Math.random()*canvasWidth,y:Math.random()*canvasHeight,r:Math.random()*2.2+.35,alpha:Math.random()*.65+.15,speed:Math.random()*.22+.05,drift:(Math.random()-.5)*.18,depth:Math.random()});}
}
function drawAtmosphere(){
  if(!context)return;
  context.clearRect(0,0,canvasWidth,canvasHeight); pointer.x+=(pointer.targetX-pointer.x)*.08; pointer.y+=(pointer.targetY-pointer.y)*.08;
  const gradient=context.createRadialGradient(canvasWidth*.5,canvasHeight*.42,20,canvasWidth*.5,canvasHeight*.42,canvasWidth*.65);gradient.addColorStop(0,'rgba(143,99,24,.09)');gradient.addColorStop(1,'rgba(0,0,0,0)');context.fillStyle=gradient;context.fillRect(0,0,canvasWidth,canvasHeight);
  context.save();context.globalCompositeOperation='screen';
  for(const particle of particles){particle.y-=particle.speed;particle.x+=particle.drift;if(particle.y<-10){particle.y=canvasHeight+10;particle.x=Math.random()*canvasWidth}const distance=Math.hypot(particle.x-pointer.x,particle.y-pointer.y);const attraction=Math.max(0,1-distance/170);const x=particle.x+(pointer.x-particle.x)*attraction*.12;const y=particle.y+(pointer.y-particle.y)*attraction*.12;const radius=particle.r+attraction*1.8;context.beginPath();context.arc(x,y,radius,0,Math.PI*2);context.fillStyle=`rgba(231,183,65,${particle.alpha+attraction*.3})`;context.shadowBlur=8+attraction*8;context.shadowColor='#d4af37';context.fill();}
  context.shadowBlur=0;context.lineWidth=1.2;context.strokeStyle='rgba(206,155,42,.19)';
  for(let ribbon=0;ribbon<3;ribbon++){context.beginPath();const y=canvasHeight*(.2+ribbon*.38);for(let x=-40;x<canvasWidth+50;x+=18){const wave=Math.sin(x*.007+ribbon+performance.now()*.00018)*(30+ribbon*7);const cursorBend=Math.max(0,1-Math.abs(x-pointer.x)/500)*((pointer.y-y)*.04);if(x===-40)context.moveTo(x,y+wave+cursorBend);else context.lineTo(x,y+wave+cursorBend)}context.stroke();}
  context.restore();if(!prefersReducedMotion)requestAnimationFrame(drawAtmosphere);
}
function startLuxuryMotion(){resizeCanvas();drawAtmosphere();window.addEventListener('resize',resizeCanvas);if(prefersReducedMotion)return;loginStage.addEventListener('pointermove',event=>{pointer.targetX=event.clientX;pointer.targetY=event.clientY;cursorGlow.style.transform=`translate(${event.clientX}px,${event.clientY}px) translate(-50%,-50%)`;cursorGlow.style.opacity='1';loginStage.style.setProperty('--bg-x',`${(event.clientX/window.innerWidth-.5)*-14}px`);loginStage.style.setProperty('--bg-y',`${(event.clientY/window.innerHeight-.5)*-10}px`);localizedBlur.style.setProperty('--blur-x',`${event.clientX}px`);localizedBlur.style.setProperty('--blur-y',`${event.clientY}px`);const bounds=loginCard.getBoundingClientRect();const overCard=event.clientX>=bounds.left&&event.clientX<=bounds.right&&event.clientY>=bounds.top&&event.clientY<=bounds.bottom;if(overCard){localizedBlur.classList.add('active');loginCard.classList.add('focus-active')}else{localizedBlur.classList.remove('active');loginCard.classList.remove('focus-active')}const rotateX=((event.clientY-(bounds.top+bounds.height/2))/bounds.height)*-8;const rotateY=((event.clientX-(bounds.left+bounds.width/2))/bounds.width)*8;loginCard.style.transform=`perspective(900px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`});loginCard.addEventListener('focusin',()=>{localizedBlur.classList.add('active');loginCard.classList.add('focus-active')});loginCard.addEventListener('focusout',event=>{if(!loginCard.contains(event.relatedTarget)){localizedBlur.classList.remove('active');loginCard.classList.remove('focus-active')}});loginStage.addEventListener('pointerleave',()=>{pointer.targetX=-500;pointer.targetY=-500;cursorGlow.style.opacity='0';localizedBlur.classList.remove('active');loginCard.classList.remove('focus-active');loginStage.style.setProperty('--bg-x','0px');loginStage.style.setProperty('--bg-y','0px');loginCard.style.transform=''});}
/* Event Calendar Event Handlers */
document.addEventListener('click',event=>{
  const closeEventModal=()=>{const modal=document.querySelector('#eventModal');if(modal)modal.classList.add('hidden')};
  const openView=view=>{closeEventModal();renderView(view);document.querySelectorAll('.nav-item').forEach(nav=>nav.classList.toggle('active',nav.dataset.view===view))};
  const printEventDetails=()=>{const card=document.querySelector('#eventModal .event-detail-card');if(!card)return;const printWindow=window.open('','_blank','width=760,height=900');if(!printWindow){showToast('Allow popups to print event details');return}printWindow.document.write(`<html><head><title>Sharma Wedding - Event Details</title><style>body{font:14px Arial,sans-serif;color:#222;padding:32px}h2{font-size:24px;margin:8px 0 22px}h3{margin-top:24px;color:#8b6914;text-transform:uppercase;font-size:13px;letter-spacing:1px}.event-type-badge,.status-badge,.team-badge{display:inline-block;padding:6px 10px;border:1px solid #d9d3c9;border-radius:6px}.event-overview,.event-financial,.event-team{border-top:1px solid #ddd;padding-top:14px}.detail-row{display:flex;justify-content:space-between;padding:7px 0}.event-actions,.modal-close{display:none}.status-badge{background:#d4edda}.team-badge{margin-right:6px}</style></head><body>${card.innerHTML}</body></html>`);printWindow.document.close();printWindow.focus();printWindow.print();printWindow.close()};
  if(event.target.closest('#closeEventModal')||event.target.closest('[data-close-modal]'))closeEventModal();
  if(event.target.closest('.calendar-date:not(.empty)'))document.querySelector('#eventModal')?.classList.remove('hidden');
  if(event.target.closest('#addEventBtn')){renderView('Bookings');showToast('New booking form ready');document.querySelectorAll('.nav-item').forEach(nav=>nav.classList.toggle('active',nav.dataset.view==='Bookings'))}
  if(event.target.closest('[data-view]')){const btn=event.target.closest('[data-view]');document.querySelectorAll('.view-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');showToast(`Switched to ${btn.dataset.view} view`)}
  const actionBtn=event.target.closest('.event-actions button');
  if(actionBtn){const action=actionBtn.getAttribute('id');if(action==='editEventBtn'||action==='viewBookingBtn')openView('Bookings');else if(action==='viewInvoiceBtn')openView('Quotes');else if(action==='recordPaymentBtn')openView('Payments');else if(action==='whatsappClientBtn'){window.open('https://wa.me/919876543210?text=Hello%20Rahul%2C%20regarding%20your%20Sharma%20Wedding%20event.','_blank','noopener,noreferrer');showToast('WhatsApp opened for Rahul Kumar')}else if(action==='printEventBtn')printEventDetails();else if(action==='cancelEventBtn'&&confirm('Cancel this event?')){const status=document.querySelector('#eventModal .status-badge');if(status){status.textContent='Cancelled';status.className='value status-badge cancelled'}actionBtn.textContent='Event Cancelled';actionBtn.disabled=true;showToast('Event cancelled')}}
});
document.addEventListener('click',event=>{
  if(event.target.closest('#todayBtn')){const today=new Date();calendarState.month=today.getMonth();calendarState.year=today.getFullYear();renderView('Event Calendar');showToast('Navigated to today')}
  if(event.target.closest('#prevMonth')){calendarState.month--;if(calendarState.month<0){calendarState.month=11;calendarState.year--}renderView('Event Calendar')}
  if(event.target.closest('#nextMonth')){calendarState.month++;if(calendarState.month>11){calendarState.month=0;calendarState.year++}renderView('Event Calendar')}
  const viewButton=event.target.closest('.view-btn');
  if(viewButton){calendarState.view=viewButton.dataset.view;renderView('Event Calendar');showToast(`${viewButton.textContent} view selected`)}
});
const searchCal=document.querySelector('.search-calendar');if(searchCal)searchCal.addEventListener('input',event=>{const query=event.target.value.toLowerCase();const events=document.querySelectorAll('.event-card');events.forEach(e=>{const match=e.textContent.toLowerCase().includes(query);e.style.display=match?'':'none'})});
